ops.css:
:root {
  --espresso: oklch(16% 0.018 50);
  --cream: oklch(93% 0.026 78);
  --ember: oklch(70% 0.18 48);
  --duration-micro: 160ms;
  --duration-standard: 260ms;
  --duration-cinematic: 800ms;
  --ease-out: cubic-bezier(0.32, 0.72, 0, 1);
  --ease-snap: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-settle: cubic-bezier(0.16, 1, 0.3, 1);
}

* { box-sizing: border-box; }

.subscription-shell {
  min-height: 100%;
  width: 100%;
  padding: 28px;
  display: grid;
  place-items: center;
  container-type: inline-size;
  position: relative;
  overflow: clip;
  isolation: isolate;
  background: var(--cream);
  color: var(--espresso);
  font-family: Arial, Helvetica, sans-serif;
}

.subscription-shell::before,
.subscription-shell::after {
  content: "";
  position: absolute;
  z-index: -1;
  width: 280px;
  aspect-ratio: 1;
  border: 1px solid var(--ember);
  border-radius: 50%;
  opacity: .22;
  transform: rotate(-18deg);
}

.subscription-shell::before { inset: -98px auto auto -70px; }
.subscription-shell::after { inset: auto -84px -140px auto; transform: rotate(28deg) scale(.72); }

.coffee-card {
  width: min(100%, 430px);
  padding: 42px;
  border-radius: 13px;
  background: var(--espresso);
  color: var(--cream);
  box-shadow: 0 28px 70px oklch(16% 0.018 50 / .22);
  animation: card-enter var(--duration-cinematic) var(--ease-settle) both;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 28px;
}

.eyebrow {
  margin: 0 0 14px;
  color: var(--ember);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .14em;
  line-height: 1.2;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 49px;
  font-weight: 400;
  letter-spacing: -.045em;
  line-height: .9;
  text-wrap: balance;
}

.roast-seal {
  width: 56px;
  height: 56px;
  flex: 0 0 56px;
  display: grid;
  place-items: center;
  border: 1px solid var(--ember);
  border-radius: 50%;
  color: var(--ember);
  transition: transform var(--duration-cinematic) var(--ease-settle), opacity var(--duration-standard) var(--ease-out);
}

.roast-seal svg { width: 35px; height: 35px; }

.price-block { margin-top: 35px; }
.price-row { display: flex; align-items: baseline; gap: 7px; }
.price-row strong {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 70px;
  font-weight: 400;
  letter-spacing: -.06em;
  line-height: .8;
}
.currency { color: var(--ember); font-size: 21px; font-weight: 700; }
.cadence { font-size: 14px; opacity: .66; }
.price-block p {
  max-width: 280px;
  margin: 21px 0 0;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 16px;
  line-height: 1.45;
  text-wrap: pretty;
  opacity: .78;
}

.rule { height: 1px; margin: 28px 0; background: var(--cream); opacity: .18; }

.benefits { margin: 0; padding: 0; display: grid; gap: 14px; list-style: none; }
.benefits li { display: flex; align-items: center; gap: 14px; font-size: 14px; line-height: 1.35; }
.bean {
  width: 14px;
  height: 7px;
  flex: 0 0 14px;
  border: 1px solid var(--ember);
  border-radius: 50%;
  transform: rotate(-28deg);
}

.actions { display: grid; gap: 14px; margin-top: 35px; }
.action {
  width: 100%;
  min-height: 49px;
  padding: 0 21px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-radius: 0;
  font: 700 14px/1 Arial, Helvetica, sans-serif;
  letter-spacing: .02em;
  cursor: pointer;
  transition: transform var(--duration-micro) var(--ease-snap), opacity var(--duration-standard) var(--ease-out);
}
.action-primary { border: 1px solid var(--ember); background: var(--ember); color: var(--espresso); }
.action-secondary { border: 1px solid var(--cream); background: transparent; color: var(--cream); }
.action:focus-visible { outline: 2px solid var(--ember); outline-offset: 3px; }
.action:active { transform: translateY(2px) scale(.99); }
.action:disabled { cursor: not-allowed; opacity: .42; }

.fine-print { margin: 21px 0 0; font-size: 12px; line-height: 1.4; text-align: center; opacity: .56; }

@media (hover: hover) {
  .action:hover { transform: translateY(-2px); }
  .action-secondary:hover { opacity: .7; }
  .coffee-card:hover .roast-seal { transform: rotate(18deg) scale(1.06); }
}

.coffee-card:focus-within .roast-seal { transform: rotate(18deg) scale(1.06); }

@container (max-width: 470px) {
  .subscription-shell { padding: 14px; }
  .coffee-card { padding: 28px; }
  h1 { font-size: 42px; }
  .price-row strong { font-size: 63px; }
  .card-header { gap: 14px; }
}

@keyframes card-enter {
  from { opacity: 0; transform: translateY(21px) scale(.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
  }
}

.subscription-shell { padding: 14px; grid-template-columns: minmax(0, 1fr); }
.coffee-card { min-width: 0; justify-self: center; }
@container (max-width: 320px) {
  .coffee-card { padding: 21px; }
  .card-header { gap: 7px; }
  h1 { font-size: 35px; }
  .roast-seal { width: 42px; height: 42px; flex-basis: 42px; }
  .roast-seal svg { width: 28px; height: 28px; }
  .action { padding: 0 14px; font-size: 12px; }
}
